import{_ as e,o as d,c as a,a6 as i}from"./chunks/framework.DfoD60a6.js";const p=JSON.parse('{"title":"Spec 35 · Fork 的寫入時複製","description":"","frontmatter":{},"headers":[],"relativePath":"SPEC-35-copy-on-write.md","filePath":"SPEC-35-copy-on-write.md","lastUpdated":1795281437000}'),r={name:"SPEC-35-copy-on-write.md"};function l(s,t,o,n,c,h){return d(),a("div",null,[...t[0]||(t[0]=[i(`<h1 id="spec-35-·-fork-的寫入時複製" tabindex="-1">Spec 35 · Fork 的寫入時複製 <a class="header-anchor" href="#spec-35-·-fork-的寫入時複製" aria-label="Permalink to &quot;Spec 35 · Fork 的寫入時複製&quot;">​</a></h1><h2 id="位址空間與所有權" tabindex="-1">位址空間與所有權 <a class="header-anchor" href="#位址空間與所有權" aria-label="Permalink to &quot;位址空間與所有權&quot;">​</a></h2><p>每個行程有獨立的使用者頁表。<code>vm_fork()</code> 先準備子頁表、heap 與 stack 位置，並透過一個 4 KiB 核心暫存頁複製父行程已換出的頁面。每個交換槽位由一個 <code>VmPage</code> 持有。從未配置的頁繼續按需載入，父行程的常駐映射在準備期間受置換保護。</p><p>所有可失敗的步驟完成且呼叫者未取消後，<code>vm_clone_impl()</code> 在相同虛擬頁索引安裝子 PTE。已常駐的程式碼也可共享。對原本可寫的頁，父子 PTE 都清除 <code>W</code> 並設定 <code>PTE_COW</code>（Sv39 <code>RSW[0]</code>）。原始權限以 <code>permissions()</code> 查詢，唯讀頁保持原權限。發布 Ready 之前完成父頁表的 TLB 同步。準備失敗會銷毀子頁表及已完成的 Swap 副本，父映射仍然有效。</p><p><code>frame_refs</code> 以實體頁框索引，計算有效使用者映射的數量。<code>retain_frame()</code> 在新頁框取得第一份引用時增加全域 <code>resident</code>。<code>release_frame()</code> 只在最後一份引用消失時歸還頁框。<code>VmPage</code> 仍各自記錄 <code>physical</code>、<code>slot</code>、<code>dirty</code>、<code>pins</code> 與 <code>arrival</code>。同一共享頁框的映射具有相同 <code>arrival</code>。<code>pcb</code> 顯示的是個別行程的映射數，<code>vmstat</code> 的 <code>resident</code> 是系統的某一刻共有幾個不同常駐頁框。頁表與裝置緩衝區繼續由底層實體配置器獨立管理。</p><h2 id="寫入與釋放" tabindex="-1">寫入與釋放 <a class="header-anchor" href="#寫入與釋放" aria-label="Permalink to &quot;寫入與釋放&quot;">​</a></h2><ul><li>Store Page Fault 使用 <code>scause=15</code> 與 <code>stval</code>，先驗證存取範圍和原始寫權限。<code>resident_page()</code> 遇到 <code>PTE_COW</code> 時交給 <code>resolve_cow()</code>。Kernel Copyout 也經由此路徑，避免直接寫入共用 RAM。</li><li>若引用多於一份，先 pin 來源、取得新頁框，再複製 4 KiB。若只剩一份引用，直接恢復寫權限。成功時清除 COW 位元、設定 <code>W/A/D</code>、標記 dirty 並同步 TLB，然後才可放掉舊引用。缺頁成功由 trap handler 使用原 <code>sepc</code> 重試。配置失敗時，該 COW 來源映射和資料仍有效。</li><li><code>sbrk</code> 縮小、<code>exec()</code> 切換舊映像，以及退出時的 <code>vm_destroy_impl()</code> 都經 <code>release_page()</code> 撤銷 PTE、同步 TLB、歸還引用與槽位。Fork 的單 TCB 限制來自 <a href="./SPEC-34-threads.html">Thread 規格</a>。</li></ul><h2 id="fifo、swap-與-smp" tabindex="-1">FIFO、Swap 與 SMP <a class="header-anchor" href="#fifo、swap-與-smp" aria-label="Permalink to &quot;FIFO、Swap 與 SMP&quot;">​</a></h2><p>FIFO 選最早入駐且可置換的實體頁框。若任一映射被 pin、屬於正在準備 fork 的來源，或該位址空間正在其他 Hart 執行，就跳過整個頁框。<code>collect_eviction_mappings()</code> 用相同頁索引收集所有引用並檢查 PTE。乾淨映射可使用原本的重建來源，或保留自己的 Swap 副本。子行程若繼承父行程已換入的資料且自己沒有 backing，會標記 dirty，以便換出時保留完整內容。</p><p><code>evict_frame()</code> 先預留所需槽位，再撤銷整組 PTE 並完成本地 <code>sfence.vma</code> 和 SBI Remote SFENCE。持有 VM Gate 完成所有需要的磁碟寫入，成功才提交各映射的槽位並釋放頁框。寫入失敗會恢復所有 PTE、再同步 TLB，並歸還本次新增槽位。若既有槽位寫了一部分，恢復後的 dirty RAM 仍是有效版本。換入時各映射獨立配置頁框，成功讀完才安裝 PTE。磁碟等待允許其他 Hart 進入核心，觸及撤銷映射的行程會等 VM Gate。位址空間切換仍使用既有的 <code>satp</code> 與 TLB 同步。</p><p>套用到唯讀頁的寫入依原路徑回 <code>ERR_ADDRESS</code>。缺乏可用頁框或 Swap Slot 時可能回 <code>ERR_NO_MEMORY</code>，磁碟出錯可能回 <code>ERR_IO</code>。目前共享僅由 fork 建立，Swap Slot 不共享，亦無 ASID 最佳化。</p><h2 id="如何觀察與重現" tabindex="-1">如何觀察與重現 <a class="header-anchor" href="#如何觀察與重現" aria-label="Permalink to &quot;如何觀察與重現&quot;">​</a></h2><p><code>vmstat</code> 的 <code>shared_frames</code> 和 <code>free_frames</code> 是即時數量。其他欄位自開機累計，<code>fork_shared</code> 是成功建立的子共享映射數，對應避免的立即複製頁數。<code>cow_faults</code> 與 <code>cow_copyouts</code> 分別計數硬體 trap 和核心寫入碰到 COW 的次數，<code>cow_copies</code> 與 <code>cow_reuses</code> 分別計數實際複製和原地解除 COW。<code>shared_evictions</code> 和 <code>shared_rollbacks</code> 以共享實體頁框為計數單位。</p><p>在 WSL 和既有 Clang／QEMU CLI 工具鏈下執行：</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test-cow</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/test_thread_stage_a.py</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/test_kernel_cli.py</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/benchmark_cow.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --runs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>原始碼入口：<a href="https://github.com/johnson931128/WUWAOS/blob/main/kernel/mm/vm.c" target="_blank" rel="noreferrer">VM</a> · <a href="https://github.com/johnson931128/WUWAOS/blob/main/kernel/proc/process.c" target="_blank" rel="noreferrer">Process</a> · <a href="https://github.com/johnson931128/WUWAOS/blob/main/arch/riscv/trap.c" target="_blank" rel="noreferrer">Trap</a> · <a href="https://github.com/johnson931128/WUWAOS/blob/main/arch/riscv/hart.c" target="_blank" rel="noreferrer">Hart</a></p><h2 id="_2026-11-22-qemu-驗證" tabindex="-1">2026-11-22 QEMU 驗證 <a class="header-anchor" href="#_2026-11-22-qemu-驗證" aria-label="Permalink to &quot;2026-11-22 QEMU 驗證&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情境</th><th>結果</th></tr></thead><tbody><tr><td>常駐頁共享與父子寫入隔離</td><td><code>PASS</code>。讀取共享頁、父寫與子寫、重複寫、跨多個子行程引用、單一引用原地恢復、Lazy Page 及 RX 拒寫。</td></tr><tr><td>Kernel Copyout、exec 與退出</td><td><code>PASS</code>。pipe <code>read()</code> 寫入子行程的 COW buffer，父資料維持原值。子行程 exec 與退出後，整機空閒頁框數回到同組磁碟乾淨開機後退出的基準。</td></tr><tr><td>低常駐預算與共享頁換出</td><td><code>PASS</code>。8 框預算觸發整組換出，父子各自換入後仍讀到原值，寫入互相隔離。</td></tr><tr><td>Swap 寫入與 COW 配置失敗</td><td><code>PASS</code>。唯讀 Swap 觸發整組映射回復。24 框預算用盡且無可置換頁框時，COW Copyout 回 <code>ERR_IO</code>，共享頁框與複製計數保持原值，父子仍讀到原資料。</td></tr><tr><td>Fork 準備中途失敗</td><td><code>PASS</code>。24 槽位的 Swap 用盡前已成功複製部分子槽位，fork 回 <code>ERR_NO_MEMORY</code> 後，父資料仍可讀寫，引用、槽位與空閒頁框數回到呼叫前。</td></tr><tr><td>2／3 Hart</td><td><code>PASS</code>。父子在共同時間點開始對同一批虛擬頁寫入不同值，各自讀回正確內容。既有 SMP probe 另有真實平行派送斷言。</td></tr><tr><td>既有回歸</td><td><code>PASS</code>。Thread Stage A、Kernel Mutex 與 Thread Core 主機測試，以及 CLI 的單 Hart 直接／Flash 開機、2／3 Hart 直接／Flash 開機、WUFS redo 重播與管線。</td></tr></tbody></table><p>整機實體配置池耗盡、已成功寫入部分磁區或部分別名後才遭遇故障、GUI runtime 與長時間 SMP 壓測為 <code>NOT_RUN</code>。唯讀 Swap 案例涵蓋 VM 已撤銷映射後收到寫入錯誤的復原路徑。</p><h2 id="效能比較" tabindex="-1">效能比較 <a class="header-anchor" href="#效能比較" aria-label="Permalink to &quot;效能比較&quot;">​</a></h2><p>基準是重新建置的 <code>74fe07e</code>。兩版使用同一份 ELF、QEMU 8.2.2 <code>virt</code>、單 Hart、128 MiB、128 框預算與相同的 WUFS／Swap 設定。每組預熱一次、量測五次，共 120 筆。程式在 <code>fork()</code> 前後及 <code>wait()</code> 後讀取 <code>rdtime</code>，表列中位數。Fork 新增頁框只計使用者資料框，頁表配置另由核心管理。立即複製版的新增頁框數等於 fork 前的個別行程常駐頁數。複製量計 eager 複製或實際 COW 拆分，並包含因堆疊而複製的頁。全部樣本 Swap 讀寫皆為 0。</p><p>表內皆為「立即複製 → COW」。</p><table tabindex="0"><thead><tr><th style="text-align:right;">Heap 頁數</th><th>子行程工作</th><th style="text-align:right;">Fork（µs）</th><th style="text-align:right;">總耗時（µs）</th><th style="text-align:right;">Fork 新增使用者頁框</th><th style="text-align:right;">複製量（KiB）</th><th style="text-align:right;">Page Fault</th></tr></thead><tbody><tr><td style="text-align:right;">4</td><td>只讀</td><td style="text-align:right;">2251 → 473</td><td style="text-align:right;">3576 → 2616</td><td style="text-align:right;">8 → 0</td><td style="text-align:right;">32 → 4</td><td style="text-align:right;">0 → 1</td></tr><tr><td style="text-align:right;">4</td><td>立即 exec</td><td style="text-align:right;">2188 → 390</td><td style="text-align:right;">13830 → 7436</td><td style="text-align:right;">8 → 0</td><td style="text-align:right;">32 → 4</td><td style="text-align:right;">1 → 2</td></tr><tr><td style="text-align:right;">4</td><td>寫一頁</td><td style="text-align:right;">2648 → 904</td><td style="text-align:right;">6116 → 6139</td><td style="text-align:right;">8 → 0</td><td style="text-align:right;">32 → 8</td><td style="text-align:right;">0 → 2</td></tr><tr><td style="text-align:right;">4</td><td>寫全部 Heap 頁</td><td style="text-align:right;">2595 → 350</td><td style="text-align:right;">6087 → 2227</td><td style="text-align:right;">8 → 0</td><td style="text-align:right;">32 → 20</td><td style="text-align:right;">0 → 5</td></tr><tr><td style="text-align:right;">16</td><td>只讀</td><td style="text-align:right;">1665 → 692</td><td style="text-align:right;">3214 → 4281</td><td style="text-align:right;">20 → 0</td><td style="text-align:right;">80 → 4</td><td style="text-align:right;">0 → 1</td></tr><tr><td style="text-align:right;">16</td><td>立即 exec</td><td style="text-align:right;">988 → 575</td><td style="text-align:right;">6170 → 6934</td><td style="text-align:right;">20 → 0</td><td style="text-align:right;">80 → 4</td><td style="text-align:right;">1 → 2</td></tr><tr><td style="text-align:right;">16</td><td>寫一頁</td><td style="text-align:right;">1809 → 334</td><td style="text-align:right;">5361 → 1913</td><td style="text-align:right;">20 → 0</td><td style="text-align:right;">80 → 8</td><td style="text-align:right;">0 → 2</td></tr><tr><td style="text-align:right;">16</td><td>寫全部 Heap 頁</td><td style="text-align:right;">1424 → 518</td><td style="text-align:right;">2898 → 2560</td><td style="text-align:right;">20 → 0</td><td style="text-align:right;">80 → 68</td><td style="text-align:right;">0 → 17</td></tr><tr><td style="text-align:right;">48</td><td>只讀</td><td style="text-align:right;">2042 → 337</td><td style="text-align:right;">3590 → 2047</td><td style="text-align:right;">52 → 0</td><td style="text-align:right;">208 → 4</td><td style="text-align:right;">0 → 1</td></tr><tr><td style="text-align:right;">48</td><td>立即 exec</td><td style="text-align:right;">1936 → 408</td><td style="text-align:right;">9995 → 7386</td><td style="text-align:right;">52 → 0</td><td style="text-align:right;">208 → 4</td><td style="text-align:right;">1 → 2</td></tr><tr><td style="text-align:right;">48</td><td>寫一頁</td><td style="text-align:right;">2517 → 326</td><td style="text-align:right;">5238 → 2011</td><td style="text-align:right;">52 → 0</td><td style="text-align:right;">208 → 8</td><td style="text-align:right;">0 → 2</td></tr><tr><td style="text-align:right;">48</td><td>寫全部 Heap 頁</td><td style="text-align:right;">2335 → 316</td><td style="text-align:right;">6547 → 3773</td><td style="text-align:right;">52 → 0</td><td style="text-align:right;">208 → 196</td><td style="text-align:right;">0 → 49</td></tr></tbody></table><p>48 頁全部寫入時，COW 最後仍複製 196 KiB，並多出 49 次寫入缺頁。只讀或立即 exec 各複製 4 KiB，皆由 Heap 以外的寫入造成。12 組的 fork 中位數都下降，總耗時有三組上升。部分時間範圍重疊，例如 16 頁只讀的總耗時，基準是 2789–5287 µs，COW 是 1785–5736 µs。QEMU 的主機排程會影響時間，這些數據適合解讀複製量與缺頁成本，無法推廣為每種工作負載的總耗時保證。重跑會在 <code>build/cow-benchmark-*</code> 輸出 <code>samples.csv</code> 和 UART 紀錄。</p>`,24)])])}const y=e(r,[["render",l]]);export{p as __pageData,y as default};
